-- 114_add_asian_optimist_index_qualifiers.sql
--
-- Source-reviewed Asian Optimist Index ledger.
-- 2025 anchor: 122 Asian sailors from the official final overall classification.
-- 2026 source imports: LIRP Optimist Gold (59) and Thailand International (65).
-- Singapore Youths (106) and Nationals (83) deliberately use their existing
-- verified SailorPath regatta_results directly; their scores are not duplicated.
--
-- Identity safety: external athletes remain in a separate Index identity table
-- unless an existing SailorPath profile has the same normalized name AND NOC.
-- Sail number alone never creates a profile link.

BEGIN;

CREATE TABLE IF NOT EXISTS public.asian_optimist_index_events (
  id text PRIMARY KEY,
  name text NOT NULL,
  index_role text NOT NULL CHECK (index_role IN ('championship_anchor', 'regional_qualifier')),
  source_kind text NOT NULL CHECK (source_kind IN ('official_result', 'sailorpath_regatta')),
  host_country text NOT NULL,
  host_noc text,
  start_date date NOT NULL,
  end_date date NOT NULL,
  venue text,
  official_results_url text NOT NULL,
  official_results_source_name text NOT NULL,
  sailorpath_regatta_slug text,
  result_status text NOT NULL DEFAULT 'awaiting_final' CHECK (result_status IN ('verified', 'awaiting_final')),
  fleet_size integer,
  race_count integer,
  discard_count integer,
  is_eligible boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.asian_optimist_index_sailors (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  identity_key text NOT NULL UNIQUE,
  canonical_name text NOT NULL,
  nationality text,
  latest_sail_number text,
  gender text,
  birth_year integer,
  sailor_id uuid REFERENCES public.sailors(id) ON DELETE SET NULL,
  match_status text NOT NULL DEFAULT 'unmatched' CHECK (match_status IN ('matched', 'unmatched', 'needs_review')),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.asian_optimist_index_results (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  event_id text NOT NULL REFERENCES public.asian_optimist_index_events(id) ON DELETE CASCADE,
  index_sailor_id uuid NOT NULL REFERENCES public.asian_optimist_index_sailors(id) ON DELETE CASCADE,
  source_rank integer NOT NULL CHECK (source_rank >= 1),
  source_name text NOT NULL,
  source_sail_number text NOT NULL,
  source_nationality text,
  source_gender text,
  source_birth_year integer,
  total_score real,
  nett_score real,
  race_scores jsonb,
  source_page integer,
  verification_status text NOT NULL DEFAULT 'pending_review' CHECK (verification_status IN ('verified', 'pending_review', 'rejected')),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT asian_optimist_index_results_event_sailor_unq UNIQUE (event_id, index_sailor_id)
);

CREATE INDEX IF NOT EXISTS asian_optimist_index_events_season_date_idx
  ON public.asian_optimist_index_events (index_role, start_date);
CREATE INDEX IF NOT EXISTS asian_optimist_index_events_regatta_idx
  ON public.asian_optimist_index_events (sailorpath_regatta_slug);
CREATE INDEX IF NOT EXISTS asian_optimist_index_sailors_sailor_idx
  ON public.asian_optimist_index_sailors (sailor_id);
CREATE INDEX IF NOT EXISTS asian_optimist_index_sailors_name_noc_idx
  ON public.asian_optimist_index_sailors (nationality, canonical_name);
CREATE INDEX IF NOT EXISTS asian_optimist_index_results_event_rank_idx
  ON public.asian_optimist_index_results (event_id, source_rank);
CREATE INDEX IF NOT EXISTS asian_optimist_index_results_sailor_idx
  ON public.asian_optimist_index_results (index_sailor_id);

ALTER TABLE public.asian_optimist_index_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.asian_optimist_index_sailors ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.asian_optimist_index_results ENABLE ROW LEVEL SECURITY;

INSERT INTO public.asian_optimist_index_events (
  id, name, index_role, source_kind, host_country, host_noc, start_date, end_date,
  venue, official_results_url, official_results_source_name, sailorpath_regatta_slug,
  result_status, fleet_size, race_count, discard_count, is_eligible, updated_at
) VALUES
