INSERT INTO public.asian_optimist_index_sailors (
  identity_key, canonical_name, nationality, latest_sail_number, gender, birth_year, updated_at
)
SELECT DISTINCT ON (lower(coalesce(p.source_nationality, 'UNK')) || ':' || regexp_replace(lower(p.identity_name), '[^a-z0-9]', '', 'g'))
  lower(coalesce(p.source_nationality, 'UNK')) || ':' || regexp_replace(lower(p.identity_name), '[^a-z0-9]', '', 'g'),
  p.identity_name,
  p.source_nationality,
  p.source_sail_number,
  p.source_gender,
  p.source_birth_year,
  now()
FROM _aoi_payloads p
JOIN public.asian_optimist_index_events e ON e.id = p.event_id
ORDER BY
  lower(coalesce(p.source_nationality, 'UNK')) || ':' || regexp_replace(lower(p.identity_name), '[^a-z0-9]', '', 'g'),
  e.start_date DESC
ON CONFLICT (identity_key) DO UPDATE SET
  canonical_name = EXCLUDED.canonical_name,
  nationality = EXCLUDED.nationality,
  latest_sail_number = EXCLUDED.latest_sail_number,
  gender = COALESCE(EXCLUDED.gender, public.asian_optimist_index_sailors.gender),
  birth_year = COALESCE(EXCLUDED.birth_year, public.asian_optimist_index_sailors.birth_year),
  updated_at = now();

-- Conservative current-profile enrichment. No date of birth is copied unless it
-- is already explicitly public on the SailorPath profile; raw external birth
-- year remains on its official result row.
WITH profile_candidates AS (
  SELECT
    s.id,
    regexp_replace(lower(s.name), '[^a-z0-9]', '', 'g') AS name_key,
    CASE lower(trim(coalesce(s.nationality, '')))
      WHEN 'singapore' THEN 'SGP'
      WHEN 'sgp' THEN 'SGP'
      WHEN 'malaysia' THEN 'MAS'
      WHEN 'mas' THEN 'MAS'
      WHEN 'thailand' THEN 'THA'
      WHEN 'tha' THEN 'THA'
      WHEN 'hong kong' THEN 'HKG'
      WHEN 'hkg' THEN 'HKG'
      WHEN 'china' THEN 'CHN'
      WHEN 'chn' THEN 'CHN'
      WHEN 'india' THEN 'IND'
      WHEN 'ind' THEN 'IND'
      WHEN 'japan' THEN 'JPN'
      WHEN 'jpn' THEN 'JPN'
      WHEN 'south korea' THEN 'KOR'
      WHEN 'korea' THEN 'KOR'
      WHEN 'kor' THEN 'KOR'
      WHEN 'kuwait' THEN 'KUW'
      WHEN 'kuw' THEN 'KUW'
      WHEN 'macau' THEN 'MAC'
      WHEN 'mac' THEN 'MAC'
      WHEN 'myanmar' THEN 'MYA'
      WHEN 'mya' THEN 'MYA'
      WHEN 'oman' THEN 'OMA'
      WHEN 'oma' THEN 'OMA'
      WHEN 'qatar' THEN 'QAT'
      WHEN 'qat' THEN 'QAT'
      WHEN 'saudi arabia' THEN 'KSA'
      WHEN 'ksa' THEN 'KSA'
      WHEN 'sri lanka' THEN 'SRI'
      WHEN 'sri' THEN 'SRI'
      WHEN 'united arab emirates' THEN 'UAE'
      WHEN 'uae' THEN 'UAE'
      ELSE upper(trim(coalesce(s.nationality, '')))
    END AS nationality
  FROM public.sailors s
),
unique_profile_candidates AS (
  SELECT id, name_key, nationality,
    count(*) OVER (PARTITION BY name_key, nationality) AS match_count
  FROM profile_candidates
)
UPDATE public.asian_optimist_index_sailors a
SET sailor_id = p.id,
    match_status = 'matched',
    updated_at = now()
FROM unique_profile_candidates p
WHERE a.sailor_id IS NULL
  AND p.match_count = 1
  AND regexp_replace(lower(a.canonical_name), '[^a-z0-9]', '', 'g') = p.name_key
  AND upper(coalesce(a.nationality, '')) = p.nationality;

INSERT INTO public.asian_optimist_index_results (
  event_id, index_sailor_id, source_rank, source_name, source_sail_number,
  source_nationality, source_gender, source_birth_year, total_score, nett_score,
  race_scores, source_page, verification_status, updated_at
)
SELECT
  p.event_id,
  a.id,
  p.source_rank,
  p.source_name,
  p.source_sail_number,
  p.source_nationality,
  p.source_gender,
  p.source_birth_year,
  p.total_score,
  p.nett_score,
  p.race_scores,
  p.source_page,
  'verified',
  now()
FROM _aoi_payloads p
JOIN public.asian_optimist_index_sailors a
  ON a.identity_key = lower(coalesce(p.source_nationality, 'UNK')) || ':' || regexp_replace(lower(p.identity_name), '[^a-z0-9]', '', 'g')
ON CONFLICT (event_id, index_sailor_id) DO UPDATE SET
  source_rank = EXCLUDED.source_rank,
  source_name = EXCLUDED.source_name,
  source_sail_number = EXCLUDED.source_sail_number,
  source_nationality = EXCLUDED.source_nationality,
  source_gender = EXCLUDED.source_gender,
  source_birth_year = EXCLUDED.source_birth_year,
  total_score = EXCLUDED.total_score,
  nett_score = EXCLUDED.nett_score,
  race_scores = EXCLUDED.race_scores,
  source_page = EXCLUDED.source_page,
  verification_status = 'verified',
  updated_at = now();

DO $verify_asian_optimist_index$
DECLARE
  baseline_rows integer;
  lirp_rows integer;
  thailand_rows integer;
  direct_sources integer;
BEGIN
  SELECT count(*) INTO baseline_rows
  FROM public.asian_optimist_index_results
  WHERE event_id = '2025-asian-oceanian' AND verification_status = 'verified';
  SELECT count(*) INTO lirp_rows
  FROM public.asian_optimist_index_results
  WHERE event_id = 'langkawi-international-regatta-perdana-2026' AND verification_status = 'verified';
  SELECT count(*) INTO thailand_rows
  FROM public.asian_optimist_index_results
  WHERE event_id = 'thailand-international-sailing-championships-2026' AND verification_status = 'verified';
  SELECT count(*) INTO direct_sources
  FROM public.asian_optimist_index_events
  WHERE source_kind = 'sailorpath_regatta' AND result_status = 'verified';

  IF baseline_rows <> 122 OR lirp_rows <> 59 OR thailand_rows <> 65 OR direct_sources <> 2 THEN
    RAISE EXCEPTION 'Asian Optimist Index source count mismatch: baseline %, LIRP %, Thailand %, SailorPath direct %',
      baseline_rows, lirp_rows, thailand_rows, direct_sources;
  END IF;
END
$verify_asian_optimist_index$;

COMMIT;
